        }
        .hotel-card .price { 
            font-weight: bold; 
            color: #2e7d32; 
            margin: 0.5rem 0; 
            font-size: 1.1rem;
        }
        .hotel-card p {
            color: #2e4d25;
            line-height: 1.5;
            margin: 0.5rem 0;
        }
        .hotel-card .book-link { 
            display: block; 
            margin: 1rem auto 0 auto; 
            background: #2e7d32; 
            color: #fff; 
            border: none; 
            border-radius: 0.5rem; 
            padding: 0.7rem 1.2rem; 
            text-decoration: none; 
            font-weight: bold; 
            transition: background 0.2s;
        }
        .hotel-card .book-link:hover { 
