            box-shadow: 0 8px 24px rgba(72,115,68,0.13);
        }
        .hotel-card img {
            width: 240px;
            height: 130px;
            object-fit: cover;
            border-radius: 12px;
            margin-bottom: 1.2rem;
        }
        .hotel-card h3 {
            margin: 0 0 0.3rem 0;
            color: #305b31;
            font-size: 1.35rem;
            font-weight: 600;
        }
