INSERT INTO city_pages (page_url, title, city_name, country, heading, header_title, header_description, back_href, placeholder_text, expected_path, currencies, html) VALUES ('vestmannaeyjar.html', 'Hotels in Vestmannaeyjar', 'Vestmannaeyjar', 'Iceland', 'Available Hotels in Vestmannaeyjar', 'Boreal Horizons', 'Book your stay with secure crypto payments, and pay in fiat too.', 'index.html', NULL, NULL, 'ETH,BTC,USDT,LTC,BCH,DOGE,XRP,XMR,XNO,DASH,VET,UNI,SOL,ADA,TRN', '<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Hotels in Vestmannaeyjar</title>
    <link rel="stylesheet" href="styles.css">
    <style>
        .booking-header { 
            background: #ffeec0; 
            padding: 2rem 1rem; 
            text-align: center; 
        }
        .booking-header h1 { 
            font-weight: bold; 
            color: #2e7d32; 
            margin: 0 0 0.5rem 0; 
            font-size: 2.2rem; 
        }
        .booking-header p { 
            font-weight: bold; 
            color: #2e7d32; 
            margin: 0; 
            font-size: 1.1rem; 
        }
        .booking-container { 
            margin: 2rem auto; 
            max-width: 1200px; 
            padding: 0 1rem; 
        }
        .booking-container h2 { 
            text-align: center; 
            color: #2e4d25; 
            margin-bottom: 1rem; 
        }
        .currency-selector {
            text-align: center;
            margin: 1.5rem 0;
        }
        .currency-selector label {
            font-weight: bold;
            color: #2e4d25;
            margin-right: 0.5rem;
        }
        .currency-selector select {
            padding: 0.5rem 1rem;
            border: 2px solid #2e7d32;
            border-radius: 0.5rem;
            background: #fff;
            color: #2e4d25;
            font-size: 1rem;
            font-weight: bold;
            cursor: pointer;
        }
        .hotel-list { 
            display: flex; 
            flex-wrap: wrap; 
            gap: 2rem; 
            justify-content: center; 
        }
        .hotel-card { 
            background: #fff; 
            border-radius: 1rem; 
            box-shadow: 0 2px 8px rgba(0,0,0,0.07); 
            width: 300px; 
            padding: 1rem; 
            text-align: center; 
        }
        .hotel-card img { 
            width: 100%; 
            height: 160px; 
            object-fit: cover; 
            border-radius: 0.7rem; 
        }
        .hotel-card h3 {
            color: #2e4d25;
            margin: 0.5rem 0;
        }
        .hotel-card .hotel-chain {
            font-size: 0.9em;
            color: #2e4d25;
            margin-bottom: 0.3rem;
        }
        .hotel-card .price { 
            font-weight: bold; 
            color: #2e7d32; 
            margin: 0.5rem 0; 
            font-size: 1.1rem;
