        .hotel-card .book-link { 
            display: block; 
            margin: 1rem auto 0 auto; 
            background: #2e7d32; 
            color: #fff; 
            border: none; 
            border-radius: 0.5rem; 
            padding: 0.7rem 1.2rem; 
            text-decoration: none; 
            font-weight: bold; 
            transition: background 0.2s;
        }
        .hotel-card .book-link:hover { 
            background: #156d17; 
        }
        .back-link {
            text-align: center;
            margin: 2rem 0;
        }
        .back-link a {
            color: #2e7d32;
            text-decoration: none;
            font-weight: bold;
        }
        .back-link a:hover {
            text-decoration: underline;
        }
        footer {
            text-align: center;
            padding: 1rem 2rem;
            font-size: 0.9rem;
            background: #b2e3b2;
            color: #2e4d25;
            border-top: 1px solid #2e4d25;
            margin-top: 3rem;
        }
    </style>
</head>
<body style="background:#e6f0e6;min-height:100vh;">
